  "sin bonificación": "sans bonus",
  "{0}\n\n{1} {2} +{3} (ahora {4}).": "{0}\n\n{1} {2} +{3} (maintenant {4}).",
  "{0} aprecia lo que has dicho (+{1} afinidad)": "{0} apprécie ce que tu as dit (+{1} affinité)",
  "{0} añadido a tu diario de viaje ({1}/{2})": "{0} ajouté à ton carnet de voyage ({1}/{2})",
